INSERT INTO `projects` (`id`, `url`, `kind`, `price_czk`, `price_eur`, `comparison`, `img_before`, `img_after`, `customer`, `name`, `sorting`, `img`, `og_img`, `description`, `content`, `testimonial`, `client_photo`, `client_name`, `client_role`, `client_says`, `testimonial_source_img`, `testimonial_src`, `cta`, `created_at`, `updated_at`) VALUES

(1, 'hcms', 'pitem-web-app', '200 000,- Kč', '8 000,- €', 0, '', '', 'Toyota Kolín', 'Informační systém HCMS', 15, 'images/projects/HCMS/hcms_preview.jpg', NULL, 'Aplikace, která <strong>šetří nejméně 3 miliony korun ročně</strong>!! (1 pracovník na každé ze 3 směn)', '<p>V obdobích zvýšeného počtu abnormalit, jako jsou přechody na výrobu nového modelu, stoupají úspory až na 5 násobek.</p>rn<h6>Stručný popis</h6>rn<p>Na montážní lince ve výrobě chybí díl.rnLogistika musí díl najít a doručit dříve než se linka zastaví.rn<br>rnDíky této aplikaci to udělá rychle a efektivně.rn</p>rn<h6>Hlavní funkce:</h6>rn<ol>rn<li>rnDohledat <strong>detailní informace potřebné k vyřešení krizové situace</strong> (např. nedostatek dílů ve výrobě).rn</li>rn<li>rnPodle získaných údajů, rozhodne uživatel o vhodném postupu řešení. Doplní instrukce pro navazující procesy a <strong>záznam odešle</strong>.rn</li>rn<li>rnV další části aplikace na tabletu jsou provedeny konkrétní kroky k <strong>vyřešení problému</strong> dle předaných instrukcí.rn</li>rn</ol>', 1, 'Pavel_Baudys.jpg', 'Pavel Baudyš', 'Toyota, Ředitel řízení výroby, montáže a logistiky', 'S potěšením mohu poskytnout tuto referenci pro Ondřeje Krišku, který pracoval v naší společnosti Toyota 18 let.                        <br>rnZa tuto dobu si vybudoval reputaci klíčového člena našeho projektového týmu.rn<br>rnI díky jeho schopnostem programování aplikací došlo k zefektivnění mnoha interních procesů, což vedlo k výrazným úsporám nákladů a zlepšení efektivity.rn<br>rnJednou z nejsilnějších stránek Ondry je velká chuť rozvíjet se, což je viditelné na jeho výsledcích. To je dle mého názoru základním předpokladem pro nejen uspokojení rozdílných potřeb jednotlivých zákazníků, ale i pro <strong>překonání jejich očekávání</strong>.', 'google.png', 'https://g.co/kgs/6rn2eF', 'Chcete také ušetřit díky webové aplikaci?', '2021-04-10 18:35:45', '2023-05-25 20:35:08'),

(24, 'FRLcreator', 'pitem-web-app', '50 000,- Kč', '2 000,- €', 0, '', '', 'Toyota Kolín', 'Generátor info listů v PDF', 30, 'images/projects/FLR/flowrack_list_screen.jpg', NULL, 'Regálové listy v PDF formátu generované na základě proměnlivých dat.', '<h6>Hlavní funkce:</h6>rn<ol>rn<li>rnUmožňuje zadání parametrů (datum, období atd.) ke kterým jsou listy požadovány.rn</li>rn<li>rnImport dat z externích zdrojů.rn</li>rn<li>rnKontrola nalezených chyb.rn</li>rn<li>rnVýběr skupiny listů pro vygenerování do PDF.rn</li>rn</ol>', 1, 'Jan-Stybor.jpg', 'Jan Stybor', 'Toyota, Vedoucí projektového oddělení', '<strong>Oceňuji profesionální přístup k práci.</strong><br>rnPří vývoji aplikace důsledně  analyzuje  stav a  chce poznat současné procesy jak se provádí. rnNásledně shromažďuje požadavky od zákazníků a zjišťuje vize, které by v budoucnu chtěli do aplikace promítnout. rnPřipraví plán na základě kterého se zákazníkem dohodne na klíčových milnících. rnPři testování uživatelem  abnormality rychle odstraňuje a opakovaně  testuje.', 'google.png', 'https://maps.app.goo.gl/qbnsv8T3qkuemtUGA', NULL, '2019-02-13 23:25:36', '2023-05-25 20:34:55'),

(25, 'picker', 'pitem-web-app', '250 000,- Kč', '10 000,- €', 0, '', '', 'Ondřej Kriška', 'Řídící logistický systém - Picker', 40, 'images/projects/picker/picker_preview.jpg', NULL, 'Aplikace k vychystávání dílů ze skladu a přípravě pro dodání k montáži.', '<h6>Hlavní funkce:</h6>rn<ol>rn<li>rnvychystávka dílů ve správný čas a ve správném množstvírn</li>rn<li>rndle instrukcí na obrazovcern</li>rn<li>rnlze používat tlačítko další nebo skenovat čárové kódyrn</li>rn<li>rnobsahuje odpočet do konce operacern</li>rn</ol>rn<h6>Aplikaci je možné rozšířit např. orn</h6>rn<ol>rn<li>přihlašování uživatelůrn</li>rn<li>část pro naskladnění dílůrn</li>rn<li>sledování aktuálních množství dílůrn</li>rn<li>alertování v případě nízkých stavů zásobrn</li>rn<li>... a mnoho dalšího dle potřebyrn</li>rn</ol>rn', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2023-02-21 22:03:58', '2023-05-25 20:34:47'),

(26, 'elektro-srnak', 'pitem-web-site', '7 000,- Kč', '300,- €', 0, '', '', 'Lukáš Srnák', 'micro web - Elektro Srnák', 21, 'images/projects/elektro-srnak/elektro_srnak_preview.jpg', NULL, 'Rozsahem spíše webová vizitka než stránka pro elektrikáře.', '<h6>Info o weburn</h6>rn<p>Minimalistický web k předání základních informací o podnikateli. Zobrazuje nabídky služeb a možnost zapůjčení zařízení.rn</p>rn<p>Integrace Google Analytics a napojení na Google Search Console.rnOpenGraph pro dokonalý vzhled při sdílení na sociálních sítí a schema markup jsou též důležitým technickým SEO prvkem.rn</p>rn<p>Tvorba také veškerého textového obsahu. Vytvořil jsme i jednoduché logo. rn</p>rn<p>Za zmínku stojí ještě implementace google mapky, případně použití lightboxu na náhledy fotek a obrázků.rn</p>rn<p>Nemám informace proč, ale pan Srnák od poloviny roku 2025 tento web neprovozuje (neplatí si hosting).rn</p>', 1, 'Lukas-Srnak.jpg', 'Lukas Srnák', 'Podnikatel v oblasti elektroinstalací a stavebních prací', 'Rychlost<br> Ochota<br> Cena<br><br>rnNaprosto perfektní přístup a jednání… <br>                     <strong>Mohu vřele doporučit..!</strong>', 'google.png', 'https://goo.gl/maps/woUXU42hzWadG8JEA', 'Potřebujete i vy svou webovou vizitku?', '2023-03-11 18:33:28', '2023-05-25 21:26:55'),

(27, 'excel-tools', 'pitem-web-app', 'do 25 000,- Kč', 'up to 1.000,- €', 0, '', '', 'Toyota Kolín', 'Programováno ve VBA pro Excel', 50, 'images/projects/excel/process_combinations.jpg', NULL, 'Ukázky některých aplikací naprogramovaných ve VBA pro Excel.', 'viz popisky jednotlivých screenshotů', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2020-09-28 22:04:37', '2023-05-25 20:34:37'),

(29, 'strechyzajic', 'pitem-web-site', '20 000,- Kč', '800,- €', 1, 'images\projects\strechyzajic\before.jpg', 'images\projects\strechyzajic\after.jpg', 'Jaroslav Zajíc', 'menší web - Střechy Zajíc', 20, 'images/projects/strechyzajic/strechyzajic_preview.jpg', NULL, 'Webová stránka pro tesaře a pokrývače, kde chce ukázat co umí - a on fakt umí. A prto si zaslouží webové stránky, které to řeknou zákazníkům.', '<h6>Hlavní funkcern</h6>rn<p>Web slouží jako prezentace nabízených služeb s ukázkami realizovaných staveb a střech.rn</p>rn<p>Integrace Google Analytics a napojení na Google Search Console.rnOpenGraph pro dokonalý vzhled při sdílení na sociálních sítí a schema markup jsou též důležitým technickým SEO prvkem.rn</p>rn<p>Vytvořil jsme jednoduché logo. Tvořil jsem také veškerý textový obsah včetně článků. Google mapa nesmí u takového webu chybět.rn</p>', 1, 'Jaroslav-Zajic.jpg', 'Jaroslav Zajíc', 'Zkušený profesionál a živnostník, který staví nejen střechy', 'Webové stránky vypadají skvěle a jejich ovládání je intuitivní. rnDíky proaktivnímu přístupu a odborným radám byl celý proces snadný. rnUrčitě se obrátím znovu, až bude potřeba další práce. rn<strong>Doporučuji.</strong>', 'firmy_cz.svg', 'https://www.firmy.cz/detail/13470851-ondrej-kriska-itwebtech-brezi.html#hodnoceni', 'Chcete i vy modernizovat web své firmy a přilákat více zákazníků?', '2023-05-25 21:04:44', '2023-05-25 21:26:23'),

(30, 'pitarena-akademie-202308', 'pitem-other', '4 000,- Kč', '200,- €', 0, '', '', 'Stanislav Holcmann', 'Video - Pitbike Akademie', 42, 'images\projects\pitarena\video-pitbike-akademie.jpg', NULL, 'Video animace pro propagaci na sociální sítě. Video a emoce hýbou sítěmi.', 'Video pro propagaci na sociální síti Facebook.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Potřebujete propagovat událost nebo produkt?', '2023-08-03 06:07:27', '2023-08-03 06:07:27'),

(31, 'pitarena', 'pitem-web-site', '105 000,- Kč', '4 300,- €', 0, '', '', 'Stanislav Holcmann', 'Nabídněte lidem to co hledají', 13, 'images/projects/pitarena/pitarena_preview.jpg', NULL, 'Webové stránky, které generují desítky nových zákazníků ročně. Jak na to? Nabídněte jim online to co hledají a oni pak za vámi ochotně přijedou.', '<h6>Rozsah webu</h6>rn<ul>rn<li>Kontaktní formulář</li>rn<li>Foto a Video galerie</li>rn<li>Články, které přivádějí nové zákazníky</li>rn<li>Pokročilý registrační formulář</li>rn<li>Rezervace termínů na servis</li>rn<li>Newsletter</li>rn<li>Vytvoření několika firemních emailů</li>rn<li>Napojení na Google analytics</li>rn<li>Opengraph pro dokonalý vzhled při sdílení stránek</li>rn<li>Administrace s přihlášením administrátora</li>rn</ul>', 1, 'Stanislav-Holcmann.jpg', 'Stanislav Holcmann', 'Majitel soukromé pitbike motokrosové arény', 'Tenhle web meister dělá stránky pro nás a můžu jenom vřele doporučit.<br><br>rn<strong>Výborná komunikace,kvalitně odvedená práce,spoustu inovativních,praktických nápadů</strong>.', 'firmy_cz.svg', 'https://www.firmy.cz/detail/13470851-ondrej-kriska-itwebtech-brezi.html#hodnoceni', 'Chcete i vy získávat zákazníky skrze váš web?', '2024-03-20 16:48:16', '2025-01-02 09:48:16'),

(32, 'pitarena-reklamni-cedule', 'pitem-other', '3 000,- Kč', '150,- €', 0, '', '', 'Stanislav Holcmann', 'Reklamní cedule', 42, 'images\projects\pitarena\pitarena_cedule.jpg', NULL, 'Vytvoření designu a podkladových souborů pro velkoformátový tisk reklamní cedule nad servis.', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Chtěli byste vytvořit banner pro vaši firmu?', '2023-08-08 21:05:11', '2023-08-08 21:05:11'),

(33, 'delejme-animace', 'pitem-other', '3000,- Kč', '150,- €', 0, '', '', 'itwebtech', 'Video - Upoutání pozornosti', 43, 'images\projects\itwebtech\video_delejme_animace.jpg', NULL, 'Video animace pro propagaci na sociální sítě. Moje doporučení je - Tvořte videa.', 'Zaujmout může být v dnešní přesycené době naprostou nezbytností. Moje doporučení - Tvořte videa.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Potřebujete pomoct s tvorbou animací?', '2023-10-03 14:43:18', '2023-10-03 14:43:18'),

(34, 'vanspedition', 'pitem-web-site', '5 000,- Kč', '200,- €', 1, 'images\projects\vanspedition\before.webp', 'images\projects\vanspedition\after.gif', 'Antonín Vrbka', 'micro web - VANspedition', 25, 'images\projects\vanspedition\vanspedition_preview.webp', NULL, 'Minimalistický web, který ale obsahuje veškerý základ profesionální firemní prezentace.', '<h6>Hlavní funkcern</h6>rn<p>Profesionální firemní prezentace, která poskytne návštěvníkům veškeré základní informace o firmě.<br>rn• Kdo jsme<br>rn• Co děláme a s čím vám pomůžeme<br>rn• Jaké jsou naše hlavní přednosti<br>rn• Možnost kontaktování<br>rn</p>', 1, 'Vaclav-Pesice.png', 'Václav Pešice', 'Software developer', 'S Ondrou je skvělá spolupráce. Vždy se snaží udělat pro klienty maximum.<br>rnDělal webové stránky pro mého klienta a za velmi nízkou cenu odvedl perfektní práci.<br>rnČasto také spolupracujeme na vývoji různých webových aplikací rna vždy je radost s ním komunikovat o jejich vývoji a dalším rozvoji.<br>rn<strong>Rozhodně má moje doporučení.</strong>', 'google.png', 'https://g.co/kgs/CEs5uj', 'Chcete i vy získat svou vebovou prezentaci?', '2023-11-12 09:23:12', '2023-11-17 09:23:12'),

(35, 'yolk', 'pitem-web-site', '650,- Kč/hod.', '€ 30 /hour', 0, '', '', 'yolk studio', 'Webové programování pro agenturu.', 18, 'images/projects/yolk/yolk_preview.webp', 'images/projects/yolk/yolk_preview.jpg', 'Aktualizace obsahu i funkcionalit na více webových stránkách a webových portálech.', '<h6>Hlavní činnostirn</h6>rn<p>rn• Aktualizuji sezónní nabídky<br>rn• Upravuji funkcionality klientských dotazníků<br>rn• Vkládám aktualizovanou grafiku<br>rn• Opravuji nalezené chyby a nedokonalosti<br>rn</p>', 1, 'peter_vidlicka.jpeg', 'Peter Vidlička', 'spoluzakladatel Yolk studio', 'Ondra je velice spolehlivy a sikovny vyvojar s kterym nam vzdy hodne dobre spolupracovalo.', 'google.png', 'https://maps.app.goo.gl/nXuNG6TdNJSJs64f6', 'Potřebujete i vy pomoct s programováním?', '2025-01-07 16:46:24', '2025-01-07 16:46:24'),

(37, 'logo-realitacky', 'pitem-other', 'zdarma k webu', 'free to the site', 0, '', '', 'Realiťačky v Akci', 'Ukázka vytvořeného loga', 41, 'images\projects\realitacky\logo_realitacky_v_akci.png', NULL, 'Video ukázka vytvořeného loga dle přání klienta.', 'Logo musí být snadno zapamatovatelné a odlišné od konkurence. Pokud možno jednoduché a ve vektorovém formátu pro neměnnou kvalitu v jakékoli velikosti.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Potřebujete i vy své originální logo?', '2024-01-28 15:43:18', '2024-01-28 15:43:18'),

(38, 'clanek-na-motorkari-cz', 'pitem-other', '0,- Kč', '0,- €', 0, '', '', 'Stanislav Holcmann', 'článek na web Motorkáři.cz', 16, 'images/projects/pitarena/clanek_motorkari_cz.jpg', NULL, 'Článek, který jsem vytvořil zdarma na podporu klientova byznysu a který s drobnými úpravami vyšel na Motorkari.cz', 'Tvorba článků na weby patří mezi základní služby, které svým klientům nabízím. Důvodem k tvorběčlánků je většinou získat obsah pro návštěvníky webu:<br>rn<ol><li>rnAby měli důvod na web chodit - někteří z nich se dříve či později stanou zákazníkyrn</li><li>rnPro vyhledávače, které na základě hledaných výrazů, tedy potřeb lidí, nabízejí obsah různých webů. No a vy chcete, aby nabídli ten váš web.rn</li></ol>', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Potřebujete pomoct s psaním článků na web?', '2024-02-01 08:42:48', '2024-02-02 08:42:48'),

(39, 'vpindustry', 'pitem-web-site', '80 000,- Kč', '€ 3 500', 1, 'images\projects\vpindustry\before.webp', 'images\projects\vpindustry\after.webp', 'Miroslav Pekárek', 'Web připravený na návštěvnost z vyhledávačů', 5, 'images/projects/vpindustry/vpindustry_web_01.webp', 'images/projects/vpindustry/vpindustry_web_01.jpg', 'Nejen samotný web, ale i analýza konkurence a klíčových slov jsou zásadní, pokud chcete postavit web, který je na organickou návštěvnost připravený. V tomto projektu jsem dodal technický základ a strukturu. Navazující obsahová/SEO fáze (pravidelná práce s', '<p>rnFirma web měla, ale byl slabý v obsahu a struktuře. rn</p>', 1, 'Hana_Jaskmanicka.jpeg', 'Hana Jaskmanická', 'VP INDUSTRY, Výkonná ředitelka', 'Chtěli jsme mít pro naši firmu VP Industry s.r.o. [www.vpindustry.cz](https://www.vpindustry.cz) kvalitní a odlišné webové stránky, rnabychom byli snadno rozeznatelní od konkurenčních firem. rnProto jsme požádali pana Krišku, aby nám vytvořel <strong>web přímo na míru</strong>.<br>rnDíky individuálnímu přístupu, flexibilitě a profesionalitě odpovídá výsledek našim představám.<br>rnNyní s ním řešíme realizaci dalšího webu naší druhé společnosti a už teď se těšíme na výsledek. rnVěříme, že jeho rychlá práce, kreativita a přístup nám bude opět vyhovovat, protože už nás navnímal a ví, rnco je pro nás priorita.<br>rn<strong>Vřele doporučuji</strong>, svým individuálním přístupem dokáže přesně odhadnout přání zákazníka.', 'google.png', 'https://maps.app.goo.gl/C6iGkdZu5rCtimqq6', 'Chcete i vy web, který bude reprezentovat vaši společnost?', '2024-07-03 15:57:25', '2024-07-18 15:57:25'),

(40, 'choccoboard', 'pitem-web-app', '29 600,- Kč', '€ 1 300', 0, '', '', 'Tradiční výroba pralinek, s.r.o.', 'Strategické informace přehledně', 10, 'images/projects/choccoboard/choccoboard_01.webp', 'images/projects/choccoboard/choccoboard_01.jpg', 'Jak si urychlit práci a získat nástroj pro kvalitnější rozhodování managementu? Chce to data a jejich přehledné spracování na jedno kliknutí.', '<p>rnTato aplikace šetří čas i peníze. Vznikla na základě potřeby managementu mít neustálý přehled o tržbách a klíčových ukazatelích v reálném čase. Před aplikací trávil manažer 30 minut denně manuálním stahováním dat, což bylo neefektivní. Díky automatizaci jsou data nyní okamžitě dostupná odkudkoli, což nejen zvyšuje produktivitu, ale otevírá nové možnosti analýzy.rn</p>rn<p>rnTento přehledný dashboard přináší lepší kontrolu nad obchodními procesy a zajišťuje kvalitnější rozhodování.rn</p>', 1, 'rostislav_toman.jpeg', 'Rostislav Toman', 'Tradiční výroba pralinek, s.r.o.', 'Oceňuji vysokou odbornost a profesionalitu. Postupnými kroky jsme odladili očekávání, realitu a na základě rad i optimalizaci toku dat, zobrazení i celou logiku reportu. Zažil jsem předčená očekávání v praxi.rn<br><br>rnZ mé strany <strong>jednoznačně doporučení na spolupráci a jasná volba v příštích projektech</strong>.rn<br><br>rnUrčitě se ještě pracovně uvidíme.', 'google.png', 'https://maps.app.goo.gl/rgeMvjSTexrMaauX9', 'Chcete získat svá data přehledně na jedno kliknutí?', '2024-09-04 15:57:25', '2024-09-16 15:57:25'),

(41, 'realitacky-v-akci', 'pitem-web-site', '75 000,- Kč', '€ 3 100', 0, '', '', 'Magda Pernicová Novotná', 'Web pro realitní makléřky', 4, 'images\projects\realitackyvakci\realitackyvakci_web_01.webp', 'images\projects\realitackyvakci\realitackyvakci_web_01.jpg', 'Moderní a funkční web pro realitní kancelář. S rezervačním systémem a administračním rozhraním.', '<p>rnVytvořili jsme moderní a funkční web pro realitní kancelář, který nabízí širokou škálu nemovitostí a integrovaný rezervační systém pro rychlou a snadnou komunikaci s makléřkami. Projekt zahrnoval nejen tvorbu webu, ale i <strong>poradenství v oblasti brandu, analýzu klíčových slov a konkurence</strong>.rn</p>rn<h2>Klíčové funkce webu</h2>rn<ol>rn<li><strong>Bez měsíčních poplatků:</strong> Web není postaven na placené platformě (webflow, wordpress,...), ale je čistě naprogramovaný. Takže klienti nejsou zatíženi dodatečnými náklady, jako jsou pravidelné licenční poplatky.</li>rn<li><strong>Rezervační systém:</strong> Klienti mohou snadno rezervovat schůzky s makléřkami online.</li>rn<li><strong>Administrace nemovitostí:</strong> Intuitivní správa nemovitostí, poptávek i blogu, která nevyžaduje technické znalosti.</li>rn<li><strong>SEO optimalizace:</strong> Zaměřil jsem se na správnou strukturu webu a použití klíčových slov, aby byl web dobře vyhledatelný</li>rn<li><strong>Kontaktní formulář na každé stránce:</strong> Jednoduchá možnost kontaktu pro klienty.</li>rn</ol>', 1, 'magda_pernicova.jpeg', 'Magda Pernicová Novotná', 'Realitní makléřka', 'Profesionální, ale zároveň lidský a trpělivý přístup.<br>rnPan Kriška opravdu naslouchal mým potřebám a následně tyto informace zpracoval rnaž do mé úplné spokojenosti.rn<br>rnZároveň nemá problém vložit do webových stránek i své zkušenosti a profi um, rna ulehčil mi tak mé laické hledání a rozhodování. rn<strong>Vřele doporučuji.</strong>', 'firmy_cz.svg', 'https://www.firmy.cz/detail/13470851-ondrej-kriska-itwebtech-brezi.html#hodnoceni', 'Chcete svůj vlastní web s realitními nabídkami?', '2024-09-16 05:57:25', '2024-09-17 05:57:25'),

(42, 'josefopa', 'pitem-web-site', '43 000,- Kč', '€ 1 800', 0, '', '', 'Josef Opa', 'Web pro podnikatele v německu', 19, 'images/projects/josefopa/josefopa_web_01.webp', 'images\projects\josefopa\josefopa.jpg', 'Josef Opa – Renovace, modernizace a stavba od A do Z', '<p>rnWebová prezentace pro stavební firmu Josef Opa, která se specializuje na komplexní stavební služby. Web je plně multijazyčný (němčina a angličtina) a nabízí intuitivní a moderní přehled poskytovaných služeb. Projekt zahrnoval tvorbu jedinečného loga, decentní animace a založení profesionální emailové schránky.rn</p>rn<h2>Klíčové vlastnosti</h2>rn<ol>rn<li><strong>Bez poplatků:</strong> Stejně jako u ostatních projektů, klient není zatížen žádnými licenčními poplatky za použití webových technologií.</li>rn<li><strong>Multijazyčný web:</strong> Stránka je dostupná v němčině a angličtině, což umožňuje cílit na širší klientelu.</li>rn<li><strong>Unikátní logo:</strong> Logo bylo vytvořeno na míru, s odvážnějším a hravým stylem, který odráží osobnost klienta a jeho podnikání.</li>rn<li><strong>Decentní animace:</strong> Jemné animace, které přidávají dynamiku bez toho, aby rušily uživatelský zážitek.</li>rn<li><strong>Emailová schránka:</strong> Založil jsem a nakonfiguroval emailovou schránku ...@josefopa.cz. V podnikání určitě není tou nejlepší vizitkou mít email ...@gmail, nebo ...@seznam a podobně.</li>rn</ol>', 0, '', '0', '', '', '', '', 'Chcete i vy web, který zaujme vaše zákazníky?', '2024-10-17 05:57:25', '2024-10-17 05:57:25'),

(43, 'kempveselka', 'pitem-web-site', '30 000,- Kč', '€ 1 300', 1, 'images/projects/kempveselka/before.webp', 'images/projects/kempveselka/after.webp', 'Jana Veselá', 'Neodrazujte návštěvníky kempu zastaralým webem', 3, 'images/projects/kempveselka/kempveselka_web_01.webp', 'images/projects/kempveselka/kempveselka.jpg', 'Autokemp Veselka se potýkal s odlivem nových návštěvníků. Stávající návštěvníci stále častěji upozorňovali na problémy s webem ...', '<h2>Výchozí stav a potřeby klienta</h2>rn<p>rnWeb, který má sloužit ku prospěchu podnikání se po letech stal přesným opakem. Zájemce o ubytování v kempu odrazoval. Občas někdo zavolal s dotazem, že viděl web a není si jistý jestli kemp vůbec ještě funguje. Zavolá ale jen menšina, většina lidí prostě z webu odejde a hledá ubytování jinde.rn</p>rn<p>To byl pro paní Veselou jednoznačný argument, že je potřeba jednat.rn</p>', 1, 'jana_vesela.jpg', 'Jana Veselá', 'majitelka kempu', '100% spokojenost s vytvořením našich webových stránek. Krásný a funkční web za minimální náklady.<br><br>                     <strong>Můžeme vřele doporučit.</strong>', 'fb.png', 'https://www.facebook.com/share/p/1DfE2GejvK/', 'Chcete i vy modernizovat web své firmy a přilákat více zákazníků?', '2025-01-02 06:57:25', '2025-01-07 06:57:25');
